export const TASK_PLANNING_REQUIREMENTS_LIMITS = {
  connectionIdCodepoints: 160,
  branchCodepoints: 255,
  providerCodepoints: 40,
  modelCodepoints: 80,
  modelAlternatives: 8,
  deliverableKindCodepoints: 160,
  deliverableDescriptionCodepoints: 4000,
  commands: 64,
  commandCodepoints: 2000,
  manualSteps: 32,
  manualStepCodepoints: 2000,
  manualEvidenceItems: 16,
  manualEvidenceCodepoints: 1000,
  notApplicableReasonCodepoints: 2000,
  skills: 8,
  skillNameCodepoints: 120,
  skillPathCodepoints: 1024,
  urlCodepoints: 2048,
  aggregateUtf8Bytes: 100_000,
} as const;
const efforts: readonly TaskEffortLevel[] = ['low', 'medium', 'high', 'xhigh', 'max'];
const limits = TASK_PLANNING_REQUIREMENTS_LIMITS;
const fullSha = (value: string) => /^(?:[0-9a-f]{40}|[0-9a-f]{64})$/i.test(value);
const sameSha = (left: string | null | undefined, right: string | null | undefined) =>
  typeof left === 'string' &&
  typeof right === 'string' &&
  left.toLowerCase() === right.toLowerCase();
const choiceKey = (choice: PlanningModelChoice) =>
  JSON.stringify([choice.provider, choice.model, choice.effort]);
function invalid(path: string, message: string): never {
  throw new DomainError('INVALID_INPUT', `${path}: ${message}`);
}
function object(value: unknown, keys: readonly string[], path: string): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value))
    invalid(path, 'must be an object');
  const row = value as Record<string, unknown>;
  if (
    Object.keys(row).length !== keys.length ||
    keys.some((key) => !Object.prototype.hasOwnProperty.call(row, key)) ||
    Object.keys(row).some((key) => !keys.includes(key))
  )
    invalid(path, 'has invalid fields');
  return row;
}

/** Exact shape, bounded Unicode text, preserved order/whitespace, no defaults or source requests. */
export function parseTaskPlanningRequirements(value: unknown): TaskPlanningRequirements | null {
  if (value === null) return null;
  let bytes = 0;
  const text = (input: unknown, path: string, max: number): string => {
    if (typeof input !== 'string') invalid(path, 'must be text');
    const points = Array.from(input);
    if (points.length > max) invalid(path, `must contain at most ${max} characters`);
    if (
      points.some((point) => {
        const code = point.codePointAt(0)!;
        return code === 0 || (code >= 0xd800 && code <= 0xdfff);
      })
    )
      invalid(path, 'contains unsupported text');
    bytes += new TextEncoder().encode(input).length;
    if (bytes > limits.aggregateUtf8Bytes)
      invalid('planningRequirements', 'must contain at most 100000 UTF-8 bytes');
    return input;
  };
  const nullableText = (input: unknown, path: string, max: number) =>
    input === null ? null : text(input, path, max);
  const list = (input: unknown, path: string, maxItems: number, maxText: number): string[] => {
    if (!Array.isArray(input) || input.length > maxItems)
      invalid(path, `must be an array of at most ${maxItems} items`);
    return Array.from(input, (item, index) => text(item, `${path}[${index}]`, maxText));
  };
  const url = (input: unknown, path: string): string => {
    const result = text(input, path, limits.urlCodepoints);
    // Empty fields can be saved in an incomplete draft. Nonempty URLs must be usable public-link syntax.
    if (result !== '') {
      let parsed: URL;
      try {
        parsed = new URL(result);
      } catch {
        invalid(path, 'must be an absolute HTTPS URL');
      }
      if (
        !result.startsWith('https://') ||
        parsed.protocol !== 'https:' ||
        !parsed.hostname ||
        parsed.username ||
        parsed.password ||
        parsed.hash ||
        parsed.search ||
        result.trim() !== result
      )
        invalid(path, 'must be an absolute HTTPS URL without credentials, query or fragment');
    }
    return result;
  };
  const sha = (input: unknown, path: string): string => {
    const result = text(input, path, 64);
    if (result !== '' && !fullSha(result)) invalid(path, 'must be a full 40- or 64-hex commit ID');
    return result;
  };
  const choice = (input: unknown, path: string): PlanningModelChoice => {
    const row = object(input, ['provider', 'model', 'effort'], path);
    const provider = text(row.provider, `${path}.provider`, limits.providerCodepoints);
    const model = text(row.model, `${path}.model`, limits.modelCodepoints);
    const effort = text(row.effort, `${path}.effort`, 6);
    if (!provider.trim() || !model.trim() || !efforts.includes(effort as TaskEffortLevel))
      invalid(path, 'requires provider, model and a supported explicit effort');
    return { provider, model, effort: effort as TaskEffortLevel };
  };
  const row = object(
    value,
    [
      'schemaVersion',
      'repository',
      'models',
      'deliverable',
      'verification',
      'acceptanceWorkflow',
      'requiredSkills',
    ],
    'planningRequirements',
  );
  if (row.schemaVersion !== 1) invalid('schemaVersion', 'must be 1');
  let repository: TaskPlanningRequirements['repository'] = null;
  if (row.repository !== null) {
    const repo = object(row.repository, ['connectionId', 'baseBranch', 'baseSha'], 'repository');
    repository = {
      connectionId: text(
        repo.connectionId,
        'repository.connectionId',
        limits.connectionIdCodepoints,
      ),
      baseBranch: nullableText(repo.baseBranch, 'repository.baseBranch', limits.branchCodepoints),
      baseSha: repo.baseSha === null ? null : sha(repo.baseSha, 'repository.baseSha'),
    };
  }
  let models: TaskPlanningRequirements['models'] = null;
  if (row.models !== null) {
    const model = object(row.models, ['recommended', 'fallback', 'allowed'], 'models');
    if (!Array.isArray(model.allowed) || model.allowed.length > limits.modelAlternatives)
      invalid('models.allowed', 'must contain at most 8 choices');
    const allowed = Array.from(model.allowed, (item, index) =>
      choice(item, `models.allowed[${index}]`),
    );
    const keys = new Set(allowed.map(choiceKey));
    if (keys.size !== allowed.length) invalid('models.allowed', 'choices must be distinct');
    const recommended =
      model.recommended === null ? null : choice(model.recommended, 'models.recommended');
    const fallback = model.fallback === null ? null : choice(model.fallback, 'models.fallback');
    for (const [name, selected] of [
      ['recommended', recommended],
      ['fallback', fallback],
    ] as const)
      if (selected && !keys.has(choiceKey(selected)))
        invalid(`models.${name}`, 'must be an exact allowed choice');
    models = { recommended, fallback, allowed };
  }
  let deliverable: TaskPlanningRequirements['deliverable'] = null;
  if (row.deliverable !== null) {
    const item = object(row.deliverable, ['kind', 'description'], 'deliverable');
    deliverable = {
      kind: text(item.kind, 'deliverable.kind', limits.deliverableKindCodepoints),
      description: text(
        item.description,
        'deliverable.description',
        limits.deliverableDescriptionCodepoints,
      ),
    };
  }
  let verification: TaskPlanningRequirements['verification'] = null;
  if (row.verification !== null) {
    const item = object(row.verification, ['automated', 'manual'], 'verification');
    const automated = object(
      item.automated,
      ['commands', 'notApplicableReason'],
      'verification.automated',
    );
    const manual = object(
      item.manual,
      ['steps', 'evidence', 'notApplicableReason'],
      'verification.manual',
    );
    verification = {
      automated: {
        commands: list(
          automated.commands,
          'verification.automated.commands',
          limits.commands,
          limits.commandCodepoints,
        ),
        notApplicableReason: nullableText(
          automated.notApplicableReason,
          'verification.automated.notApplicableReason',
          limits.notApplicableReasonCodepoints,
        ),
      },
      manual: {
        steps: list(
          manual.steps,
          'verification.manual.steps',
          limits.manualSteps,
          limits.manualStepCodepoints,
        ),
        evidence: list(
          manual.evidence,
          'verification.manual.evidence',
          limits.manualEvidenceItems,
          limits.manualEvidenceCodepoints,
        ),
        notApplicableReason: nullableText(
          manual.notApplicableReason,
          'verification.manual.notApplicableReason',
          limits.notApplicableReasonCodepoints,
        ),
      },
    };
  }
  if (!Array.isArray(row.requiredSkills) || row.requiredSkills.length > limits.skills)
    invalid('requiredSkills', 'must contain at most 8 skills');
  const requiredSkills = Array.from(row.requiredSkills, (input, index): TaskPlanningSkill => {
    const at = `requiredSkills[${index}]`;
    const item = object(input, ['name', 'repositoryUrl', 'commitSha', 'path', 'downloadUrl'], at);
    const path = text(item.path, `${at}.path`, limits.skillPathCodepoints);
    if (
      path &&
      (path.startsWith('/') ||
        path.includes('\\') ||
        path.split('/').some((part) => part === '.' || part === '..' || part === ''))
    )
      invalid(`${at}.path`, 'must be a repository-relative file path');
    return {
      name: text(item.name, `${at}.name`, limits.skillNameCodepoints),
      repositoryUrl: url(item.repositoryUrl, `${at}.repositoryUrl`),
      commitSha: sha(item.commitSha, `${at}.commitSha`),
      path,
      downloadUrl: url(item.downloadUrl, `${at}.downloadUrl`),
    };
  });
  const pins = requiredSkills
    .filter((item) => item.repositoryUrl && item.commitSha && item.path)
    .map((item) => JSON.stringify([item.repositoryUrl, item.commitSha.toLowerCase(), item.path]));
  if (new Set(pins).size !== pins.length)
    invalid('requiredSkills', 'the same pinned skill must not be repeated');
  const acceptanceWorkflow = list(
    row.acceptanceWorkflow,
    'acceptanceWorkflow',
    limits.manualSteps,
    limits.manualStepCodepoints,
  );
  return {
    schemaVersion: 1,
    repository,
    models,
    deliverable,
    verification,
    acceptanceWorkflow,
    requiredSkills,
  };

nativePlanningSchema.text:
import {
  TASK_EFFORT_LEVELS,
  TASK_PLANNING_REQUIREMENTS_LIMITS as limits,
  type TaskModelRequirement,
} from '@multiplayer/server';

type Schema = Record<string, unknown>;
const object = (properties: Record<string, Schema>): Schema => ({
  type: 'object',
  properties,
  required: Object.keys(properties),
  additionalProperties: false,
});
const nullable = (value: Schema): Schema => ({ anyOf: [value, { type: 'null' }] });
const text = (maxLength: number): Schema => ({ type: 'string', maxLength });
const list = (items: Schema, maxItems: number): Schema => ({ type: 'array', items, maxItems });
const effort: Schema = { type: 'string', enum: [...TASK_EFFORT_LEVELS] };
const choice = object({
  provider: { ...text(limits.providerCodepoints), minLength: 1 },
  model: { ...text(limits.modelCodepoints), minLength: 1 },
  effort,
});
const sha = { ...text(64), description: 'Empty draft text or a full 40- or 64-hex commit ID.' };
const url = {
  ...text(limits.urlCodepoints),
  description: 'Empty draft text or an absolute HTTPS URL without credentials, query or fragment.',
};

/** Discovery shape mirrors the server parser; that exact parser remains authoritative. */
export const taskPlanningRequirementsSchema: Schema = nullable(
  object({
    schemaVersion: { type: 'integer', const: 1 },
    repository: nullable(
      object({
        connectionId: text(limits.connectionIdCodepoints),
        baseBranch: nullable(text(limits.branchCodepoints)),
        baseSha: nullable(sha),
      }),
    ),
    models: nullable(
      object({
        recommended: nullable(choice),
        fallback: nullable(choice),
        allowed: { ...list(choice, limits.modelAlternatives), uniqueItems: true },
      }),
    ),
    deliverable: nullable(
      object({
        kind: text(limits.deliverableKindCodepoints),
        description: text(limits.deliverableDescriptionCodepoints),
      }),
    ),
    verification: nullable(
      object({
        automated: object({
          commands: list(text(limits.commandCodepoints), limits.commands),
          notApplicableReason: nullable(text(limits.notApplicableReasonCodepoints)),
        }),
        manual: object({
          steps: list(text(limits.manualStepCodepoints), limits.manualSteps),
          evidence: list(text(limits.manualEvidenceCodepoints), limits.manualEvidenceItems),
          notApplicableReason: nullable(text(limits.notApplicableReasonCodepoints)),
        }),
      }),
    ),
    acceptanceWorkflow: list(text(limits.manualStepCodepoints), limits.manualSteps),
    requiredSkills: list(
      object({
        name: text(limits.skillNameCodepoints),
        repositoryUrl: url,
        commitSha: sha,
        path: text(limits.skillPathCodepoints),
        downloadUrl: url,
      }),
      limits.skills,
    ),
  }),
);

export const taskModelRequirementSchema: Schema = nullable(
  object({
    allowed: {
      ...list(
        object({
          provider: { ...text(limits.providerCodepoints), minLength: 1 },
          model: { ...text(limits.modelCodepoints), minLength: 1 },

nativeToolPlanSchema.text:
  }, ['descriptionMarkdown', 'storySections', 'links']);
}

function boundedArray<T>(value: unknown, label: string, maximum: number, parse: (item: unknown, index: number) => T): T[] {
  if (!Array.isArray(value) || value.length > maximum) throw new ToolInputError(`${label} must be an array with at most ${maximum} entries`);
  return Array.from(value, parse);
}

function planTaskIds(value: unknown, label: string): string[] {
  return boundedArray(value, label, 1000, (item, index) => text(item, `${label}[${index}]`, 160));
}

function publicationDraftPlan(value: unknown): SaveTaskPublicationDraftInput['plan'] {
  const plan = record(value, 'plan');
  exactKeys(plan, ['optionKey', 'waves', 'unassignedTaskIds', 'dependencies']);
  const waves = boundedArray(plan.waves, 'plan.waves', 32, (value, index) => {
    const wave = record(value, `plan.waves[${index}]`);
    exactKeys(wave, ['id', 'name', 'taskIds']);
    return {
      ...(wave.id === undefined ? {} : { id: text(wave.id, `plan.waves[${index}].id`, 160) }),
      name: text(wave.name, `plan.waves[${index}].name`, 80),
      taskIds: planTaskIds(wave.taskIds, `plan.waves[${index}].taskIds`),
    };
  });
  const unassignedTaskIds = planTaskIds(plan.unassignedTaskIds, 'plan.unassignedTaskIds');
  const assigned = [...waves.flatMap((wave) => wave.taskIds), ...unassignedTaskIds];
  const selectedTaskIds = new Set(assigned);
  if (assigned.length > 1000 || selectedTaskIds.size !== assigned.length) throw new ToolInputError('plan must contain at most 1000 distinct assigned tasks');
  const dependencies = boundedArray(plan.dependencies, 'plan.dependencies', 1000, (value, index) => {
    const dependency = record(value, `plan.dependencies[${index}]`);
    exactKeys(dependency, ['taskId', 'dependsOnTaskIds']);
    const taskId = text(dependency.taskId, `plan.dependencies[${index}].taskId`, 160);
    const dependsOnTaskIds = planTaskIds(dependency.dependsOnTaskIds, `plan.dependencies[${index}].dependsOnTaskIds`);
    if (!selectedTaskIds.has(taskId) || new Set(dependsOnTaskIds).size !== dependsOnTaskIds.length || dependsOnTaskIds.some((id) => id === taskId || !selectedTaskIds.has(id))) throw new ToolInputError('plan dependencies must refer to other selected tasks without duplicates');
    return { taskId, dependsOnTaskIds };
  });
  if (new Set(dependencies.map((row) => row.taskId)).size !== dependencies.length) throw new ToolInputError('plan dependency rows must be distinct');
  return { optionKey: nullableText(plan.optionKey, 'plan.optionKey', 160), waves, unassignedTaskIds, dependencies };
}

const revisionSchema: JsonObject = { type: 'integer', minimum: 1, maximum: Number.MAX_SAFE_INTEGER };
const planTaskIdsSchema: JsonObject = { type: 'array', maxItems: 1000, uniqueItems: true, items: stringSchema('Selected draft task ID.', 160) };
const publicationDraftPlanSchema = objectSchema({
  optionKey: { anyOf: [stringSchema('Proposed poll option key from tanduna.proposals.get.', 160), { type: 'null' }], description: 'Null while preparing; a saved option is required before submission.' },
  waves: { type: 'array', maxItems: 32, items: objectSchema({
    id: stringSchema('Existing server-issued wave ID from the saved draft; omit for a new wave.', 160),
    name: stringSchema('Human wave name, in the intended wave order.', 80),
    taskIds: planTaskIdsSchema,
  }, ['name', 'taskIds']) },
  unassignedTaskIds: { ...planTaskIdsSchema, description: 'Selected tasks not assigned to a named wave; placed after named waves.' },
  dependencies: { type: 'array', maxItems: 1000, items: objectSchema({ taskId: stringSchema('Selected task ID.', 160), dependsOnTaskIds: planTaskIdsSchema }, ['taskId', 'dependsOnTaskIds']) },
}, ['optionKey', 'waves', 'unassignedTaskIds', 'dependencies']);

nativeRequirementHandlers.text:
    name: 'tanduna.tasks.get_requirements',
    title: 'Read saved task planning requirements',
    description: 'Read scoped maintainer planning requirements, current task revision, model instructions and field-specific completeness. Saved observations are host-supplied; completeness is not execution readiness or model attestation.',
    inputSchema: objectSchema({ projectSlug: stringSchema('Project slug.', 200), taskId: stringSchema('Task ID.', 300) }, ['projectSlug', 'taskId']),
    annotations: readAnnotations,
  },
  mutates: false,
  async run({ app, actorId }, value) {
    const input = record(value); exactKeys(input, ['projectSlug', 'taskId']);
    const scoped = await app.getScopedTask(text(input.projectSlug, 'projectSlug', 200), text(input.taskId, 'taskId', 300), actorId);
    return app.getTaskPlanningRequirements(actorId, scoped.task.id);
  },
},
{
  definition: {
    name: 'tanduna.tasks.set_requirements',
    title: 'Save task planning requirements',
    description: 'Replace or clear planning requirements for an editable maintainer draft without claim, frozen publication or execution history. expectedRevision is mandatory; read again after a conflict. Incomplete drafts save with specific feedback. The host supplies source observations; callers cannot submit them. This does not attest a model, execute work or approve publication.',
    inputSchema: objectSchema({ projectSlug: stringSchema('Project slug.', 200), taskId: stringSchema('Task ID.', 300), expectedRevision: revisionSchema, requirements: taskPlanningRequirementsSchema }, ['projectSlug', 'taskId', 'expectedRevision', 'requirements']),
    annotations: writeAnnotations({ destructive: true }),
  },
  mutates: true,
  async run({ app, actorId }, value) {
    const input = record(value); exactKeys(input, ['projectSlug', 'taskId', 'expectedRevision', 'requirements']);
    const expectedRevision = positiveRevision(input.expectedRevision, 'expectedRevision');
    const requirements = parseTaskPlanningRequirements(input.requirements);
    const scoped = await app.getScopedTask(text(input.projectSlug, 'projectSlug', 200), text(input.taskId, 'taskId', 300), actorId);
    await app.setTaskPlanningRequirements(actorId, scoped.task.id, requirements, expectedRevision);
    return app.getTaskPlanningRequirements(actorId, scoped.task.id);
  },
},
{
  definition: {
    name: 'tanduna.tasks.set_model_requirement',
    title: 'Save permitted task model instructions',
    description: 'Replace or clear permitted models and minimum effort on an editable maintainer task. Supply the exact last observed expectedRequirement, including null, to reject conflicting changes. The existing setter normalizes these instructions. Align them with saved planning preferences; this does not attest an executed model or change runner authorization.',
    inputSchema: objectSchema({ projectSlug: stringSchema('Project slug.', 200), taskId: stringSchema('Task ID.', 300), requirement: taskModelRequirementSchema, expectedRequirement: taskModelRequirementSchema }, ['projectSlug', 'taskId', 'requirement', 'expectedRequirement']),
    annotations: writeAnnotations({ destructive: true }),
  },
  mutates: true,
  async run({ app, actorId }, value) {
    const input = record(value); exactKeys(input, ['projectSlug', 'taskId', 'requirement', 'expectedRequirement']);
    let requirement, expectedRequirement;
    try {
      requirement = parseMcpTaskModelRequirement(input.requirement);
      expectedRequirement = parseMcpTaskModelRequirement(input.expectedRequirement);
    } catch (error) {
      throw new ToolInputError((error as Error).message);
    }
    const scoped = await app.getScopedTask(text(input.projectSlug, 'projectSlug', 200), text(input.taskId, 'taskId', 300), actorId);
    await app.setTaskModelRequirement(actorId, scoped.task.id, requirement, expectedRequirement);
    return app.getTaskPlanningRequirements(actorId, scoped.task.id);
  },
},
{
  definition: {
    name: 'tanduna.tasks.brief',
    title: 'Get a task work brief',
