/** Deterministic missing-field/source feedback bound to the same immutable V3 review. */
export function planningPublicationFindings(request: TaskPublicationReviewRequest): TaskPublicationReviewFinding[] {
  if (request.snapshot.schemaVersion !== 3) return [];
  return request.snapshot.tasks.flatMap(task => {
    const completeness = taskPlanningCompleteness(structuredClone(task.planningRequirements) as TaskPlanningRequirements | null, {
      projectId: request.snapshot.projectId, fields: structuredClone(task.fields) as TaskRevisionFields,
      modelRequirement: structuredClone(task.modelRequirement) as TaskModelRequirement | null,
      ...(task.planningSourceEvidence ? { sourceEvidence: structuredClone(task.planningSourceEvidence) as TaskPlanningSourceEvidence } : {}),
    });
    return completeness.issues.length ? [{ taskId: task.taskId, category: 'scope' as const, severity: 'blocking' as const,
      detail: completeness.issues.map(issue => `${issue.path} (${issue.code}): ${issue.message}`).join(' ').slice(0, 1800) }] : [];
  });
}
export function applyPlanningPublicationFeedback(request: TaskPublicationReviewRequest, result: TaskPublicationReviewResult): TaskPublicationReviewResult {
  if (result.status !== 'PASSED' && result.status !== 'CHANGES_REQUESTED') return result;
  const missing = planningPublicationFindings(request);
  if (!missing.length) return result;
  const findings = [...result.findings, ...missing].slice(0, 100);
  if (result.findings.length + missing.length > 100) findings.push({ taskId: null, category: 'scope', severity: 'blocking', detail: 'Additional tasks have incomplete requirements. Read each task planning completeness result before creating a corrected plan.' });
  return { ...result, status: 'CHANGES_REQUESTED', summary: 'This plan needs complete task requirements and confirmed source references. Correct the listed fields and submit a new plan revision.', findings,
    limitations: [...result.limitations, 'Planning completeness and source observations do not attest the contributor model, passing QA or runner execution readiness.'] };
}

